import React from "react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` ΓÇö the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (┬º12b) ΓÇö the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited ΓåÆ renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) ΓÇö an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` ΓÇö this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <Typography size="sm" isSkeleton />
    }
    // no seat cap at this phase ΓåÆ no honest scarcity reason ΓåÆ stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` ΓÇö the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ΓçÆ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `┬╖` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // ┬º5a: icon matches the FONT-SIZE of the text beside it ΓÇö `sm`
                        // (14px) ΓçÆ `size-3.5`. ┬º5.0a: below `size-5` ΓçÆ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) ΓÇö but they're still TWO SEPARATE cluster items, since the
                    // `┬╖` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}Γé½ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@sb-components/starci/blocks/consultant/ConsultantCard/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` ΓÇö the consultant directory's browse surface: a
 * match count above the cards, across the loading ΓåÆ empty ΓåÆ content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ΓçÆ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ΓçÆ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` ΓÇö this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region ΓÇö the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved ΓÇö ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` ΓÇö `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (┬º14d.1) ΓÇö the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton


            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}


            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,

    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={skeletonTiles}  />
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}

                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={tiles}  />
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

import { SparkleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentAiSelectionAsk` ΓÇö the "Ask AI" pill that pops up next to a text
 * selection inside lesson content. Selection tracking and portal positioning are
 * DOM behaviour handled outside the block; it takes an `anchor` point. `isNew`
 * toggles a "New" chip beside the pill.
 */

/** A viewport point (already resolved by the caller ΓÇö e.g. a selection rect). */
export interface ContentAiSelectionAskAnchor {
    /** Distance from the left edge of the viewport, in pixels. */
    x: number
    /** Distance from the top edge of the viewport, in pixels. */
    y: number
}

/** Props for {@link ContentAiSelectionAsk}. */
export interface ContentAiSelectionAskProps {
    /** Fired when the reader taps the pill ΓÇö the caller opens the AI side-thread. */
    onOpen: () => void
    /** Where to plant the pill, in viewport coordinates. */
    anchor: ContentAiSelectionAskAnchor
    /** `true` -> carries a "New" chip, for the first releases while readers learn the feature exists. */
    isNew?: boolean
    className?: string
}

/**
 * The "ask AI about this passage" pill, planted at a caller-supplied viewport
 * point. See the file header for the scope cut around selection tracking.
 *
 * @param props - {@link ContentAiSelectionAskProps}
 */
const ContentAiSelectionAsk = ({
    onOpen,
    anchor,
    isNew = false,
    className,
}: ContentAiSelectionAskProps) => (
    // Positioning ONLY on this outer box (┬º13z exempts the anchor point itself, not a row
    // rhythm) ΓÇö the `Button`<->`Chip` seam is owned by `StackH` below, never hand-written here.
    <div
        style={{ position: "fixed", left: anchor.x, top: anchor.y }}
        className={cn("z-50 -translate-x-1/2 -translate-y-full", className)}
    >
        <StackH
            identity={{ tier: "block", component: "ContentAiSelectionAsk" }}
            gap={2}
            principle="icon-text"
            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            items={[
                () => (
                    <Button
                        label="Ask AI"
                        variant="primary"
                        size="sm"
                        prefixIcon={SparkleIcon}
                        onPress={onOpen}
                        isElevated
                    />
                ),
                ...(isNew ? [() => (
                    <Chip
                        text="New"
                        tone="accent"
                    />
                )] : []),
            ]}
        />
    </div>
)

export { ContentAiSelectionAsk }

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardList } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentHeader` ΓÇö the lesson-identity cluster atop the reading screen: a
 * `PageHeader` cluster carrying read state, reading time, challenge count, and
 * learning outcomes. One chip per cluster (`starci-fe/no-adjacent-chip`): read
 * state takes the chip, reading time and challenge count ride as muted text with
 * an inline icon. `isRead` is a state; losing the outcomes card and `isSkeleton`
 * are each their own leaf. The breadcrumb trail always exists.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface ContentHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One line of "what you'll learn" ΓÇö plain data, the block builds the row. */
export interface ContentHeaderOutcome {
    /** Stable React key. */
    key: string
    /** The outcome sentence, already localized by the caller (blocks carry no i18n). */
    text: string
}

/** Props for {@link ContentHeader}. */
export interface ContentHeaderProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<ContentHeaderCrumb>
    /** Lesson title. */
    title: string
    /** One-sentence summary of the lesson. */
    description?: string
    /**
     * `true` ΓåÆ the learner has finished this lesson. This is the ONE classifying
     * fact in the meta cluster, so it is the one that gets a chip.
     */
    isRead?: boolean
    /** Estimated reading time in MINUTES ΓÇö the block adds the word itself. */
    minutesRead?: number
    /** How many challenges hang off this lesson ΓÇö the block adds the word itself. */
    challengeCount?: number
    /**
     * The "what you'll learn" lines. Empty or omitted ΓåÆ the whole section is not
     * drawn at all: a lesson with no stated outcomes should say nothing, not show
     * an empty card.
     */
    outcomes?: Array<ContentHeaderOutcome>
    /**
     * `true` ΓåÆ every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (┬º12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Lesson identity cluster at the top of the reading screen. See the file header
 * for the full contract.
 *
 * @param props - {@link ContentHeaderProps}
 */
const ContentHeader = ({
    breadcrumbItems,
    title,
    description,
    isRead = false,
    minutesRead,
    challengeCount,
    outcomes,
    isSkeleton = false,
}: ContentHeaderProps) => {
    const hasOutcomes = isSkeleton || (outcomes?.length ?? 0) > 0

    return (
        <StackV
            identity={{ tier: "block", component: "ContentHeader" }}
            principle="sibling-stack"
            explain="Page identity cluster and outcomes card are same-kind peers on the lesson header ΓÇö not group-boundary, because they are repeating header sections rather than nested groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <PageHeader
                        isSkeleton={isSkeleton}
                        breadcrumb={() =>
                            isSkeleton || breadcrumbItems?.length ? (
                                // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                                <div className="w-fit">
                                    <Breadcrumbs
                                        collapseOnMobile
                                        collapseFrom={4}
                                        items={breadcrumbItems ?? []}
                                        isSkeleton={isSkeleton}
                                    />
                                </div>
                            ) : undefined
                        }
                        title={title}
                        description={description}
                        meta={() =>
                            <StackH
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                isSkeleton={isSkeleton}
                                items={[
                                    ...(isSkeleton ? [() => (
                                        <Chip isSkeleton />
                                    )] : isRead ? [() => (
                                        <Chip
                                            tone="success"
                                            icon={CheckCircleIcon}
                                            text="Read"
                                        />
                                    )] : []),
                                    ...(isSkeleton ? [() => (
                                        <Typography size="xs" color="muted" isSkeleton />
                                    )] : [
                                        ...(minutesRead != null ? [() => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                text={`${minutesRead} min read`}
                                            />
                                        )] : []),
                                        ...(challengeCount != null ? [() => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                text={`${challengeCount} challenges`}
                                            />
                                        )] : []),
                                    ]),
                                ]}
                            />
                        }
                    />
                ),
                ...(hasOutcomes ? [() => (
                    <SurfaceCardList
                        label="What you will learn"
                        isSkeleton={isSkeleton}
                        items={(outcomes ?? []).map((outcome) => ({
                            key: outcome.key,
                            leadingIcon: CheckCircleIcon,
                            leadingIconColor: "success",
                            title: outcome.text,
                        }))}
                    />
                )] : []),
            ]}
        />
    )
}

export { ContentHeader }

import React from "react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `CourseBrief` ΓÇö the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `┬╖`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     *  NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules ┬╖ ~14h ┬╖ 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator ΓÇö
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `┬╖`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) ΓÇö the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners ΓÇö the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` ΓåÆ the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data ΓÇö the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (┬º12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS ΓÇö units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (┬º14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={
                breadcrumbItems?.length
                    ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                        // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                        <div className="w-fit">
                            {/* collapse: below @app-sm or trail ΓëÑ 4 crumbs ΓåÆ back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={skeleton}
                            />
                        </div>
                    )
                    : undefined
            }
            title={title}
            description={description}
            meta={
                metaParts.length > 0
                    ? () => (
                        <Typography size="xs" color="muted" text={metaParts.join(" ┬╖ ")} />
                    )
                    : undefined
            }
        />
    )
}

/** `CourseBrief.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React from "react"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"

/**
 * BLOCK ΓÇö `CourseQaHeader`: the PAGE-IDENTITY cluster at the top of a course
 * Q&A screen ΓÇö trail, title, description, nothing else.
 *
 * SIBLING OF `LeaderboardHeader`/`FoundationsHeader`, NOT A COPY. Every ported
 * screen wraps `PageHeader` in its own domain-named block rather than the
 * screen touching the composite directly (rule 1). This board carries no meta
 * row for the same reason `LeaderboardHeader` doesn't: the facts (question
 * count, filter, sort) live in the honest-strip/toolbar below, not the header.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface CourseQaHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseQaHeader}. */
export interface CourseQaHeaderProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseQaHeaderCrumb>
    /** Page title, e.g. "Q&A". */
    title: string
    /** One-sentence description of what this Q&A board is for. */
    description?: string
    /**
     * `true` ΓåÆ every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (┬º12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Course Q&A page identity ΓÇö trail, title, description. See the file header
 * for why this stays a thin sibling of `LeaderboardHeader`/`FoundationsHeader`
 * rather than a fresh idea.
 *
 * @param props - {@link CourseQaHeaderProps}
 */
const CourseQaHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: CourseQaHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems?.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems ?? []}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { CourseQaHeader }

import React from "react"
import { MagnifyingGlassIcon } from "@phosphor-icons/react"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { QuestionPreviewRow } from "./QuestionPreviewRow"
import { SkeletonQuestionRow } from "./SkeletonQuestionRow"
import { type CourseQaQuestionItem } from "./types"

export type {
    CourseQaQuestionAuthor,
    CourseQaQuestionScope,
    CourseQaQuestionItem,
    CourseQaCurrentUser,
    CourseQaQuestionListProps,
} from "./types"

/**
 * `CourseQaQuestionList` ΓÇö the course-wide Q&A roll-up region: the async
 * lifecycle (loading ΓåÆ error ΓåÆ search-empty ΓåÆ content) around a flush divide-y
 * question list plus a pager. The Content leaf renders `QuestionPreviewRow`, a
 * marked collapsed-look stand-in with real data, until the real per-question
 * thread block lands. Four leaves: `Loading`, `Error`, `Empty` (filter matched
 * nothing; true zero-ever is `CourseQaInvite` a layer up), `Content`.
 */

/** How many placeholder rows mirror the list while the first page loads ΓÇö matches `CourseQaSkeleton.tsx`. */
const SKELETON_ROW_COUNT = 4

const ERROR_TITLE = "Couldn't load the question list"
const RETRY_LABEL = "Retry"
const EMPTY_TITLE = "No questions match the current filter"
const EMPTY_DESCRIPTION = "Try a different filter or search term."

/** The Loading branch's rows ΓÇö see *1 for why these are NOT `SurfaceCardList.isSkeleton`. */
const skeletonItems = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => <SkeletonQuestionRow />,
    }))

/** The Content branch's real rows ΓÇö each a {@link QuestionPreviewRow} (*2 gap stand-in). */
const questionItems = (
    questions: ReadonlyArray<CourseQaQuestionItem>,
    currentUserId: string | null,
): Array<SurfaceCardListItem> =>
    questions.map((question) => ({
        key: question.id,
        content: () => <QuestionPreviewRow question={question} currentUserId={currentUserId} />,
    }))

/**
 * The course-wide Q&A roll-up list. See the file header for the full contract,
 * the GAP note on `QaQuestionThread` (*2), and the remaining judgement calls.
 *
 * @param props - {@link CourseQaQuestionListProps}
 */
const CourseQaQuestionList = ({
    questions,
    isLoading,
    error,
    onRetry,
    page,
    totalPages,
    onPageChange,
    currentUserId,
    currentUser,
    onAnswered,
    pagerAriaLabel,
    isSkeleton = false,
}: import("./types").CourseQaQuestionListProps) => {
    // `currentUser`/`onAnswered` are pure pass-through for the future `QaQuestionThread`
    // swap (*2/GAP) ΓÇö `QuestionPreviewRow` (today's stand-in) does not consume them.
    void currentUser
    void onAnswered

    const emptyContent: AsyncContentEmptyProps = {
        icon: MagnifyingGlassIcon,
        title: EMPTY_TITLE,
        description: EMPTY_DESCRIPTION,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel: RETRY_LABEL,

    }

    return (
        <AsyncContent
            // *5 ΓÇö an external override (`isSkeleton`) converges on the same Loading
            // branch as the list's own fetch flag (`isLoading`).
            isLoading={isSkeleton || isLoading}
            skeleton={() => (
                <SurfaceCardList
                    identity={{ tier: "block", component: "CourseQaQuestionList" }}
                    items={skeletonItems()}
                />
            )}
            isEmpty={questions.length === 0}
            emptyContent={emptyContent}
            error={error}
            errorContent={errorContent}
            content={() => (
                <StackV
                    identity={{ tier: "block", component: "CourseQaQuestionList" }}
                    principle="sibling-stack"
                    explain="Question list and pager are same-kind peers in the roll-up column ΓÇö not group-boundary, because they are repeating list sections rather than nested groups."
                    items={[
                        () => (
                            <SurfaceCardList
                                items={questionItems(questions, currentUserId)}
                            />
                        ),
                        ...(totalPages > 1
                            ? [
                                // *4 ΓÇö `Pagination` hard-codes its own aria-label; a wrapping
                                // <nav> is how the caller's `pagerAriaLabel` still names the region.
                                () => (
                                    <nav aria-label={pagerAriaLabel}>
                                        <Pagination
                                            currentPage={page}
                                            totalPages={totalPages}
                                            onPageChange={onPageChange}
                                        />
                                    </nav>
                                ),
                            ]
                            : []),
                    ]}
                />
            )}
        />
    )
}

