    Label,
    Popover,
    PopoverContent,
} from "@heroui/react"
import {
    BellIcon,
    ChecksIcon,
    CircleIcon,
    MagnifyingGlassIcon,
    ShoppingCartIcon,
    SidebarSimpleIcon,
    UserIcon,
} from "@phosphor-icons/react"
import { NavbarLanguageMenu } from "./NavbarLanguageMenu"
import { NavbarThemeSwitch } from "./NavbarThemeSwitch"
import type { NavbarLanguageOption } from "./types"
import { Logo } from "@sb-components/atoms/display/Logo/Logo"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Badge } from "@sb-components/atoms/display/Badge/Badge"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { UserCell } from "@sb-components/composites/lists/UserCell/UserCell"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button, type IconComponent } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { InputButtonLike } from "@sb-components/composites/buttons/InputButtonLike/InputButtonLike"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ListRow } from "@sb-components/composites/lists/List/List"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import { HideAbove } from "@sb-components/frames/HideAbove/HideAbove"
import { ScrollArea } from "@sb-components/frames/ScrollArea/ScrollArea"
import { ShowFrom } from "@sb-components/frames/ShowFrom/ShowFrom"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `Navbar` ΓÇö the sticky top app bar. Two structural leaves: the desktop row
 * (route pills + inline language/theme) and the mobile collapsed row (icon bar
 * + drawer trigger) are different compositions. Signed-in vs guest, empty vs
 * busy badges, and drawer open vs closed are data, so they are states inside
 * the matching leaf. Both leaves render the same component (the `@app-md:`
 * rules live in its className), so the mobile leaf pins a narrow
 * `renderClassName` frame to force the collapsed row into view.
 */

/** One top-level desktop/mobile route entry. */
export interface NavLinkItem {
    /** Stable id ΓÇö also the value reported to the desktop pill group. */
    id: string
    /** Visible label, already localized by the caller. */
    label: string
    /** Whether this entry matches the current route. */
    isActive?: boolean
    /** Fired when the entry is picked (desktop pill or mobile drawer row). */
    onPress: () => void
}

export type { NavbarLanguageOption }

/** One row in the notification popover's list. */
export interface NavbarNotificationItem {
    /** Stable id. */
    id: string
    /** Primary line, already resolved/translated by the caller. */
    title: string
    /** Optional secondary line. */
    subtitle?: string
    /** Already-formatted relative time (e.g. "3 hours ago") ΓÇö locale math is app wiring. */
    timeLabel: string
    /** `false` renders the unread dot leading the row. */
    isRead: boolean
}

/** Notification bell data + the callbacks its popover fires. */
export interface NavbarNotificationsData {
    /** Drives the bell's count badge; `0` hides it. */
    unreadCount: number
    /** Most-recent page, newest first. */
    items: Array<NavbarNotificationItem>
    /** `true` while the FIRST page is loading (no cache yet). */
    isLoading: boolean
    /** Already-translated error message; `null`/absent ΓåÆ no error branch. */
    error?: string | null
    /** Fired when a row is pressed (mark-read + navigate is the caller's job). */
    onItemPress: (item: NavbarNotificationItem) => void
    /** Fired by the header's bulk action. */
    onMarkAllRead: () => void
    /** Fired by the footer's deep-link action. */
    onSeeAll: () => void
    /** Fired by the error branch's retry button. */
    onRetry: () => void
}

/** The signed-in viewer, as far as the account menu's header row needs to know. */
export interface NavbarAccountUser {
    /** Drives the avatar fallback + the header row's primary line. */
    username: string
    /** Shown as the header row's secondary `@handle` line. */
    email?: string
    /** Uploaded avatar URL; `Avatar`'s own fallback chain covers the rest. */
    avatarUrl?: string | null
}

/** One row of the account dropdown's action list ΓÇö covers BOTH the guest rows
 * (sign in / sign up) and the authed rows (dashboard / profile / sign out); the
 * caller decides which set to hand in via {@link NavbarAccountData.isAuthed}. */
export interface NavbarAccountMenuItem {
    /** Stable id. */
    id: string
    /** Visible label, already localized. */
    label: string
    /** Leading glyph, atom-scale (`size-5`) as this block owns the icon column. */
    icon?: IconComponent
    /** `true` ΓåÆ renders in the destructive tone (e.g. "Sign out"). */
    isDanger?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Account menu data + the one state flag its header/list branch on. */
export interface NavbarAccountData {
    /** `true` ΓåÆ header shows {@link NavbarAccountData.user}; `false` ΓåÆ the guest prompt. */
    isAuthed: boolean
    /** Present only when {@link NavbarAccountData.isAuthed}. */
    user?: NavbarAccountUser
    /** `true` while the shared "who am I" query has not resolved yet. */
    isLoading: boolean
    /** The action rows below the header (see {@link NavbarAccountMenuItem}). */
    menuItems: Array<NavbarAccountMenuItem>
}

/** Props for {@link Navbar}. */
export interface NavbarProps {
    /** Fired when the brand mark is pressed ΓÇö routing "home" is the caller's call. */
    onLogoPress: () => void
    /** Route entries ΓÇö the ONE source both the desktop pills and the mobile drawer read. */
    navItems: Array<NavLinkItem>

    /** Placeholder text for the desktop search field; doubles as the mobile icon's aria-label. */
    searchPlaceholder: string
    /** Already-formatted shortcut hint (e.g. `"Ctrl K"`, `"ΓîÿK"`) ΓÇö OS detection is app wiring. */
    shortcutLabel: string
    /** Fired when the search trigger (field or icon) is pressed, or Ctrl/Cmd+K is hit. */
    onSearchPress: () => void

    /** Selectable locales. */
    languages: Array<NavbarLanguageOption>
    /** Currently active locale ΓÇö must match one entry's `code`. */
    activeLocale: string
    /** Fired with the newly picked locale code. */
    onLocaleChange: (code: string) => void

    /** Dark-mode on/off (controlled). */
    isDarkMode: boolean
    /** Fired with the new on/off state. */
    onThemeToggle: (isDark: boolean) => void

    /** Items currently in the cart; `0` hides the count badge. */
    cartCount: number
    /** Fired when the cart icon is pressed. */
    onCartPress: () => void

    /** Notification bell data + callbacks. */
    notifications: NavbarNotificationsData
    /** Account menu data + callbacks. */
    account: NavbarAccountData

    /** Whether the mobile navigation drawer is open. Controlled by the caller. */
    isMobileDrawerOpen: boolean
    /** Fired on backdrop click / Escape / the close button / a row navigating away. */
    onMobileDrawerOpenChange: (isOpen: boolean) => void
}

interface ShortcutHintProps {
    shortcutLabel: string
}
const ShortcutHint = ({ shortcutLabel }: ShortcutHintProps) => (
    <Kbd><Kbd.Content>{shortcutLabel}</Kbd.Content></Kbd>
)

/**
 * The sticky top app bar. See the file header for the full reuse ledger and the
 * judgement calls this port makes.
 *
 * @param props - {@link NavbarProps}
 */
const Navbar = ({
    onLogoPress,
    navItems,
    searchPlaceholder,
    shortcutLabel,
    onSearchPress,
    languages,
    activeLocale,
    onLocaleChange,
    isDarkMode,
    onThemeToggle,
    cartCount,
    onCartPress,
    notifications,
    account,
    isMobileDrawerOpen,
    onMobileDrawerOpenChange,
}: NavbarProps) => {
    const [isNotificationsOpen, setNotificationsOpen] = useState(false)
    const [isAccountOpen, setAccountOpen] = useState(false)

    // Ctrl/Cmd+K ΓÇö carried over from the real component (see file header): it only
    // ever calls a prop this block already owns, so it is not new app wiring.
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            const isK = event.key?.toLowerCase() === "k"
            if (!isK || !(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            onSearchPress()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [onSearchPress])

    const activeNavId = navItems.find((item) => item.isActive)?.id ?? ""

    const notificationSkeletonRows = [0, 1, 2].map((row) => (
        <ListRow key={row} title="" isSkeleton />
    ))

    const notificationRows = notifications.items.map((item, index) => (
        <ListRow
            key={item.id}
            leading={!item.isRead ? (
                ({ isSkeleton }: SkeletonProps) =>
                    isSkeleton ? null : <CircleIcon weight="fill" aria-hidden focusable="false" className="size-2 text-accent-soft-foreground" />
            ) : undefined}
            title={item.title}
            subtitle={item.subtitle}
            meta={() => <Typography size="xs" color="muted" text={item.timeLabel} />}
            onPress={() => notifications.onItemPress(item)}
            divider={index < notifications.items.length - 1}
        />
    ))

    const accountMenuHeader = (
        <AsyncContent
            isLoading={account.isLoading}
            skeleton={() => <UserCell username="" isSkeleton />}
            content={() => (account.isAuthed && account.user ? (
                <UserCell
                    username={account.user.username}
                    avatar={account.user.avatarUrl}
                    handle={account.user.email}
                />
            ) : (
                <StackH
                    principle="icon-text"
                    explain="Avatar beside its guest prompt ΓÇö not name-handle, because this pairs a glyph with instructional text rather than a name/handle identity."
                    items={[
                        () => <Avatar icon={UserIcon} fallback="icon" />,
                        () => <Typography size="sm" color="muted" text="Sign in to save your learning progress" />,
                    ]}
                />
            ))}
        />
    )

    const mobileNavRows = navItems.map((item) => (
        <Button
            key={item.id}
            variant={item.isActive ? "secondary" : "ghost"}
            align="start"
            label={item.label}
            onPress={() => {
                item.onPress()
                onMobileDrawerOpenChange(false)
            }}
        />
    ))

    return (
        <nav className="sticky top-0 z-50 border-b border-default bg-surface">
            {/* primary row ΓÇö fixed 4rem tall, matching the real bar's height contract */}
            <div className="h-16 min-h-16">
                <StackH
                    principle="block-boundary"
                    explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                    items={[
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups brand mark and desktop route pills on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <span
                                            role="button"
                                            tabIndex={0}
                                            aria-label="StarCi Academy"
                                            onClick={onLogoPress}
                                            onKeyDown={(event) => {
                                                if (event.key === "Enter" || event.key === " ") onLogoPress()
                                            }}
                                            className="inline-flex cursor-pointer"
                                        >
                                            <Logo />
                                        </span>
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <ButtonRadioGroup
                                                    items={navItems.map((item) => ({
                                                        value: item.id,
                                                        content: <Typography size="sm" text={item.label} />,
                                                    }))}
                                                    value={activeNavId}
                                                    onChange={(id) => navItems.find((item) => item.id === id)?.onPress()}
                                                    ariaLabel="Main navigation"
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackH
                                principle="flex-action"
                                explain="Groups search, locale, theme, cart, account, and mobile menu triggers on one horizontal peer row so they share a single hit baseline."
                                items={[
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <InputButtonLike
                                                    placeholder={searchPlaceholder}
                                                    icon={MagnifyingGlassIcon}
                                                    suffix={() => <ShortcutHint shortcutLabel={shortcutLabel} />}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={MagnifyingGlassIcon}
                                                    ariaLabel={searchPlaceholder}
                                                    onPress={onSearchPress}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <ShowFrom
                                            at="md"
                                            body={() => (
                                                <StackH
                                                    principle="flex-action"
                                                    explain="Groups language and theme controls on one horizontal peer row so they share a single hit baseline."
                                                    items={[
                                                        () => (
                                                            <NavbarLanguageMenu
                                                                languages={languages}
                                                                activeLocale={activeLocale}
                                                                onLocaleChange={onLocaleChange}
                                                            />
                                                        ),
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    () => (
                                        <HeroButton
                                            isIconOnly
                                            variant="tertiary"
                                            className="rounded-full"
                                            aria-label="Cart"
                                            onPress={onCartPress}
                                        >
                                            <Badge color="accent" count={cartCount}>
                                                <ShoppingCartIcon className="size-5" />
                                            </Badge>
                                        </HeroButton>
                                    ),
                                    ...(account.isAuthed
                                        ? [
                                            () => (
                                                <Popover isOpen={isNotificationsOpen} onOpenChange={setNotificationsOpen}>
                                                    <HeroButton
                                                        isIconOnly
                                                        variant="tertiary"
                                                        className="rounded-full"
                                                        aria-label="Notifications"
                                                    >
                                                        <Badge color="danger" count={notifications.unreadCount}>
                                                            <BellIcon className="size-5" />
                                                        </Badge>
                                                    </HeroButton>
                                                    <PopoverContent placement="bottom right" className="w-[360px]">
                                                        {/* inset-exception: vendor popover body padding, wider than tall, not a surface inset */}
                                                        <StackV
                                                            principle="control-pad"
                                                            explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row."
                                                            items={[
                                                                () => (
                                                                    <StackH
                                                                        principle="sibling-stack"
                                                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                        items={[
                                                                            () => <Typography size="sm" weight="bold" text="Notifications" />,
                                                                            ...(notifications.unreadCount > 0
                                                                                ? [
                                                                                    () => (
                                                                                        <Button
                                                                                            isIconOnly
                                                                                            variant="ghost"
                                                                                            size="sm"
                                                                                            prefixIcon={ChecksIcon}
                                                                                            ariaLabel="Mark all as read"
                                                                                            onPress={notifications.onMarkAllRead}
                                                                                        />
                                                                                    ),
                                                                                ]
                                                                                : []),
                                                                        ]}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <AsyncContent
                                                                        isLoading={notifications.isLoading && notifications.items.length === 0}
                                                                        skeleton={() => (
                                                                            <StackV
                                                                                principle="sibling-stack"
                                                                                explain="Same-kind peer stack of notification skeleton rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                items={[() => notificationSkeletonRows]}
                                                                            />
                                                                        )}
                                                                        isEmpty={notifications.items.length === 0}
                                                                        emptyContent={{ title: "No notifications yet" }}
                                                                        error={notifications.error}
                                                                        errorContent={{
                                                                            title: notifications.error ?? "",
                                                                            onRetry: notifications.onRetry,
                                                                            retryLabel: "Try again",
                                                                        }}
                                                                        content={() => (
                                                                            <ScrollArea
                                                                                axis="y"
                                                                                principle="flex-fill"
                                                                                explain="Owns local vertical overflow for the notification list so long threads do not grow the popover past the viewport."
                                                                                body={() => (
                                                                                    <StackV
                                                                                        principle="sibling-stack"
                                                                                        explain="Same-kind peer stack of notification rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                                                                        items={[() => notificationRows]}
                                                                                    />
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                ),
                                                                () => (
                                                                    <Button
                                                                        variant="ghost"
                                                                        size="sm"
                                                                        label="See all"
                                                                        onPress={notifications.onSeeAll}
                                                                    />
                                                                ),
                                                            ]}
                                                        />
                                                    </PopoverContent>
                                                </Popover>
                                            ),
                                        ]
                                        : []),
                                    () => (
                                        <Dropdown isOpen={isAccountOpen} onOpenChange={setAccountOpen}>
                                            <HeroButton
                                                isIconOnly
                                                variant="tertiary"
                                                className="rounded-full"
                                                aria-label="Account"
                                            >
                                                {account.isAuthed ? (
                                                    <Avatar
                                                        size="sm"
                                                        name={account.user?.username}
                                                        src={account.user?.avatarUrl ?? undefined}
                                                        seed={account.user?.email ?? account.user?.username}
                                                    />
                                                ) : (
                                                    <UserIcon className="size-5" />
                                                )}
                                            </HeroButton>
                                            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                                                <StackV
                                                    principle="cell-pad"
                                                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                                    body={() => accountMenuHeader}
                                                />
                                                <Divider />
                                                <Dropdown.Menu aria-label="Account">
                                                    <Dropdown.Section>
                                                        {account.menuItems.map((item) => {
                                                            const Icon = item.icon
                                                            return (
                                                                <Dropdown.Item
                                                                    key={item.id}
                                                                    id={item.id}
                                                                    textValue={item.label}
                                                                    className={item.isDanger ? "text-danger-soft-foreground" : undefined}
                                                                    onPress={item.onPress}
                                                                >
                                                                    {Icon ? <Icon className="size-5" /> : null}
                                                                    <Label className={item.isDanger ? "text-danger-soft-foreground" : undefined}>{item.label}</Label>
                                                                </Dropdown.Item>
                                                            )
                                                        })}
                                                    </Dropdown.Section>
                                                </Dropdown.Menu>
                                            </Dropdown.Popover>
                                        </Dropdown>
                                    ),
                                    () => (
                                        <HideAbove
                                            at="md"
                                            body={() => (
                                                <Button
                                                    isIconOnly
                                                    variant="ghost"
                                                    prefixIcon={SidebarSimpleIcon}
                                                    ariaLabel="Open mobile menu"
                                                    onPress={() => onMobileDrawerOpenChange(true)}
                                                />
                                            )}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>

            {/* mobile navigation drawer ΓÇö the ONE local (non-overlay-store) drawer this run's
                contract calls for; every other overlay in this system opens through the global
                store (see canon Rule 13), this one is controlled straight by the caller. */}
            <DrawerShell
                isOpen={isMobileDrawerOpen}
                onOpenChange={onMobileDrawerOpenChange}
                placement="right"
                title="Mobile menu"
                body={() => (
                    <StackV
                        principle="group-boundary"
                        explain="Separates mobile route list from language/theme controls so each region keeps its own seam owner ΓÇö not sibling-stack, because these are distinct section roles rather than repeating peers."
                        items={[
                            () => (
                                <StackV
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of mobile route rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                    items={[() => mobileNavRows]}
                                />
                            ),
                            () => <Divider />,
                            () => (
                                <StackV
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack of language and theme rows ΓÇö not group-boundary, because these are repeating preference peers rather than section groups."
                                    items={[
                                        () => (
                                            <StackH
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Typography size="sm" text="Language" />,
                                                    () => (
                                                        <NavbarLanguageMenu
                                                            languages={languages}
                                                            activeLocale={activeLocale}
                                                            onLocaleChange={onLocaleChange}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackH
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={[
                                                    () => <Typography size="sm" text="Theme" />,
                                                    () => (
                                                        <NavbarThemeSwitch
                                                            isDarkMode={isDarkMode}
                                                            onThemeToggle={onThemeToggle}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            ),
                        ]}
                    />
                )}
            />
        </nav>
    )
}

export { Navbar }

import React from "react"
import { cn } from "@heroui/react"
import {
    BookmarkSimpleIcon,
    ChartBarIcon,
    CreditCardIcon,
    DesktopIcon,
    GraduationCapIcon,
    PaintBrushIcon,
    PencilSimpleIcon,
    ShieldCheckIcon,
    SlidersHorizontalIcon,
    StarIcon,
    WalletIcon,
} from "@phosphor-icons/react"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { CollapsibleSidebar } from "@sb-components/starci/blocks/navigation/CollapsibleSidebar/CollapsibleSidebar"
import { DesktopNavRow } from "./DesktopNavRow"

/**
 * `SettingsSidebarNav` ΓÇö the account-settings destination list, drawn as a
 * collapsible desktop rail and, below `@app-md`, a sticky horizontal pill bar.
 * Two structural leaves ΓÇö `DesktopRail` (collapsible `Link`-shaped rows with a
 * divider between groups) and `MobilePillBar` (a flattened rounded-full chip
 * row). Both render the same component; only the container width differs, so
 * each story shows the branch its own `@app-md` query resolves to. `activeHref`
 * is data, so within each leaf it is a state.
 *
 * Held: sticky-under-navbar desktop height host, mobile sticky pill surface, and
 * active/inactive chip `cn` ΓÇö no existing frame/composite owns those shapes
 * (`ShowFrom`/`HideAbove` lack sticky+height; `NavigationRail` owns column fill;
 * `RailShell` sticky uses `top-24`, not `top-16`).
 */

/** Every account-settings destination this rail can offer ΓÇö the closed vocabulary the block owns. */
export type SettingsDestinationKey =
    | "editProfile"
    | "appearance"
    | "security"
    | "sessions"
    | "courseHistory"
    | "aiSettings"
    | "aiSubscription"
    | "aiUsage"
    | "bookmarks"
    | "membership"
    | "installments"

/** One settings destination ΓÇö TYPED DOMAIN DATA only: which one, and where it navigates. */
export interface SettingsNavItem {
    /** Which destination this row is ΓÇö drives its icon + label (block-owned table below). */
    key: SettingsDestinationKey
    /** Absolute href the row navigates to. */
    href: string
}

/**
 * A cluster of destinations rendered together. No `label` field: every real group is
 * unlabelled (see `src`'s `getSettingsGroups` ΓÇö only a divider separates them), so adding
 * an unused caption prop would be inventing a case no screen asks for (┬º14d.3).
 */
export interface SettingsNavGroup {
    /** Stable React key for the group ΓÇö not shown, only used for reconciliation + the divider count. */
    key: string
    /** The destinations in this group, in display order. */
    items: Array<SettingsNavItem>
}

/** Destination ΓåÆ label. The block's own wording (┬º14d.1), never handed in by the caller. */
export const DESTINATION_LABEL: Record<SettingsDestinationKey, string> = {
    editProfile: "Edit profile",
    appearance: "Appearance",
    security: "Security",
    sessions: "Login sessions",
    courseHistory: "Learning history",
    aiSettings: "AI settings",
    aiSubscription: "AI plan",
    aiUsage: "AI usage",
    bookmarks: "Saved",
    membership: "Membership plan",
    installments: "Installments",
}

/** Destination ΓåÆ icon. Same glyphs `src`'s `nav.tsx` maps, so porting this table reads as ONE control. */
export const DESTINATION_ICON: Record<SettingsDestinationKey, TypographyIcon> = {
    editProfile: PencilSimpleIcon,
    appearance: PaintBrushIcon,
    security: ShieldCheckIcon,
    sessions: DesktopIcon,
    courseHistory: GraduationCapIcon,
    aiSettings: SlidersHorizontalIcon,
    aiSubscription: CreditCardIcon,
    aiUsage: ChartBarIcon,
    bookmarks: BookmarkSimpleIcon,
    membership: StarIcon,
    installments: WalletIcon,
}

/** Props for {@link SettingsSidebarNav}. */
export interface SettingsSidebarNavProps {
    /** Grouped destinations, in display order. */
    groups: Array<SettingsNavGroup>
    /** Which destination's `href` is being viewed right now. */
    activeHref: string
    /** Fired with a destination's `href` when its row/pill is pressed. */
    onNavigate: (href: string) => void
    /** Heading shown atop the desktop rail (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /** `localStorage` key the collapsed flag persists under, so the choice survives navigation. */
    storageKey: string
    /** Accessible name for the mobile pill nav landmark. Defaults to {@link title}. */
    mobileNavAriaLabel?: string
}

/**
 * The settings destination rail. See the file header for the reused `CollapsibleSidebar`
 * gap, the two still-inlined gaps, the enum-owned vocabulary, the `@app-md` port, and the
 * two structural leaves.
 *
 * @param props - {@link SettingsSidebarNavProps}
 */
const SettingsSidebarNav = ({
    groups,
    activeHref,
    onNavigate,
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    mobileNavAriaLabel,
}: SettingsSidebarNavProps) => {
    // Mobile leaf flattens every group into one scroll strip ΓÇö grouping only matters to the
    // desktop rail's dividers, the mobile bar has no room to spare on a section caption.
    const flatItems = groups.flatMap((group) => group.items)

    return (
        <StackV
            identity={{ tier: "block", component: "SettingsSidebarNav" }}
            principle="group-boundary"
            explain="Separates the desktop rail from the mobile pill bar so each leaf keeps its own seam owner ΓÇö not sibling-stack, because these are alternate structural leaves rather than repeating peers."
            items={[
                () => (
                    // Held: sticky-under-navbar + viewport-minus-chrome height ΓÇö no named frame.
                    <div className="hidden shrink-0 @app-md:sticky @app-md:top-16 @app-md:block @app-md:h-[calc(100dvh-4rem)]">
                        <CollapsibleSidebar
                            title={title}
                            collapseLabel={collapseLabel}
                            expandLabel={expandLabel}
                            storageKey={storageKey}
                        >
                            {groups.map((group, index) => (
                                <React.Fragment key={group.key}>
                                    {index > 0 ? <Divider /> : null}
                                    <StackV
                                        principle="sibling-stack"
                                        explain="Same-kind peer stack of settings rows ΓÇö not group-boundary, because rows are repeating siblings rather than section groups."
                                        items={group.items.map((item) => () => (
                                            <DesktopNavRow
                                                item={item}
                                                isActive={item.href === activeHref}
                                                onNavigate={onNavigate}
                                            />
                                        ))}
                                    />
                                </React.Fragment>
                            ))}
                        </CollapsibleSidebar>
                    </div>
                ),
                () => (
                    // Held: mobile sticky pill landmark + chip active/inactive cn.
                    <nav aria-label={mobileNavAriaLabel ?? title} className="sticky top-16 z-30 @app-md:hidden">
                        <div className="overflow-x-auto border-b border-default bg-background/80 backdrop-blur-xl">
                            <StackH
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                items={flatItems.map((item) => () => {
                                    const isActive = item.href === activeHref
                                    const Icon = DESTINATION_ICON[item.key]
                                    return (
                                        <button
                                            type="button"
                                            aria-current={isActive ? "page" : undefined}
                                            onClick={() => onNavigate(item.href)}
                                            className={cn(
                                                "shrink-0 rounded-full border px-3 py-2 transition-colors",
                                                isActive ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                            )}
                                        >
                                            <StackH
                                                principle="icon-text"
                                                explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                items={[
                                                    () => <Icon aria-hidden focusable="false" className="size-4 shrink-0" />,
                                                    () => <Typography size="sm" text={DESTINATION_LABEL[item.key]} noWrap />,
                                                ]}
                                            />
                                        </button>
                                    )
                                })}
                            />
                        </div>
                    </nav>
                ),
            ]}
        />
    )
}

export { SettingsSidebarNav }

import React from "react"
import type { ReactNode } from "react"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { FillAvailable } from "@sb-components/frames/FillAvailable/FillAvailable"
import { Stage } from "@sb-components/frames/Stage/Stage"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnrollGate, type EnrollGateProps } from "@sb-components/starci/blocks/learn/EnrollGate/EnrollGate"
import { ContentAiFab } from "@sb-components/starci/blocks/learn/ContentAiFab/ContentAiFab"
import {
    ContentAiSelectionAsk,
    type ContentAiSelectionAskAnchor,
} from "@sb-components/starci/blocks/learn/ContentAiSelectionAsk/ContentAiSelectionAsk"

/**
 * `LearnShell` ΓÇö the wrapper mounted once per `/learn/**` scope. Five
 * structural leaves, each gaining or losing a whole node:
 *   - `RailSurface`        ΓÇö rail mounted beside `children`, one floating FAB.
 *   - `NoRailSurface`      ΓÇö no rail; `children` fills the width.
 *   - `SelectionAskActive` ΓÇö gains the `ContentAiSelectionAsk` pill alongside
 *     the FAB.
 *   - `AiSuppressed`       ΓÇö `isAssessmentLive` loses both AI trigger nodes.
 *   - `EnrollGated`        ΓÇö the whole rail+children row is replaced by
 *     `EnrollGate`.
 */

/** Which `/learn/**` surface is currently active ΓÇö drives whether a rail mounts. */
export type LearnSurface = "content" | "personalProject" | "leaderboard" | "other"

/** Surfaces whose real rail body (out of scope here, see file header) exists in the real app. */
const RAIL_SURFACES: ReadonlySet<LearnSurface> = new Set(["content", "leaderboard"])

/** Rail persistence + bounds ΓÇö mirrors the real `learn/layout.tsx` rail's own defaults. */
const RAIL_STORAGE_KEY = "learn-shell-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 256
const RAIL_MAX_WIDTH = 480
const RAIL_ARIA_LABEL = "Drag to resize the side panel"
const RAIL_LOADING_LABEL = "Loading side panel"

/**
 * Fields `LearnShell` relays into `EnrollGate` ΓÇö see the file header's
 * "`preview` IS A RELAYED SLOT" note for why `preview`/`price` ride along with
 * `title`/`description`, plus the `onEnroll` callback the gate needs to fire.
 */
export interface LearnShellEnrollGateProps
    extends Pick<EnrollGateProps, "title" | "description" | "preview" | "price"> {
    /** Fired when the learner takes the gate's enroll CTA. */
    onEnroll: () => void
}

/**
 * A resolved, already-positioned "ask AI about this selection" request ΓÇö see
 * the file header for why `LearnShell` never tracks the selection itself.
 */
export interface LearnShellSelectionAsk {
    /** Viewport point to plant the pill at (already resolved by the caller). */
    anchor: ContentAiSelectionAskAnchor
    /** `true` ΓåÆ the pill carries the "New" badge. */
    isNew?: boolean
}

/** Props for {@link LearnShell}. */
export interface LearnShellProps {
    /** Which `/learn/**` surface is mounted right now ΓÇö drives which rail body would mount. */
    activeSurface: LearnSurface
    /** `true` ΓåÆ the active surface requires enrollment the viewer does not have; replaces the whole body with `EnrollGate`. */
    isEnrollGated: boolean
    /** `true` ΓåÆ a timed/live assessment is running; suppresses BOTH AI triggers regardless of `isEnrollGated`. */
    isAssessmentLive: boolean
    /** `title`/`description`/`preview`/`price` relayed into `EnrollGate`, plus its `onEnroll`. Required only while `isEnrollGated`. */
    enrollGateProps?: LearnShellEnrollGateProps
    /** Fired when the floating AI trigger is pressed ΓÇö the real layout opens the AI chat rail/drawer in response. */
    onOpenAiChat: () => void
    /** `true` ΓåÆ that chat surface is already open, so `ContentAiFab` hides instead of floating on top of it. */
    isAiChatOpen?: boolean
    /** The current text-selection ask request, already resolved+positioned by the caller. `null`/omitted ΓåÆ no selection to react to. */
    selectionAsk?: LearnShellSelectionAsk | null
    /** Fired when the selection-ask pill is pressed. */
    onOpenSelectionAsk: () => void
    /** The active route's own content ΓÇö the one place `ReactNode` is valid above frame tier (┬º12). */
    children: ReactNode
}

/**
 * The `/learn/**` layout shell. See the file header for the full contract, the
 * scope gaps left deliberately open, and why `LeaderboardCategoryNav` was not
 * reused despite the inventory hint.
 *
 * @param props - {@link LearnShellProps}
 */
const LearnShell = ({
    activeSurface,
    isEnrollGated,
    isAssessmentLive,
    enrollGateProps,
    onOpenAiChat,
    isAiChatOpen = false,
    selectionAsk = null,
    onOpenSelectionAsk,
    children,
}: LearnShellProps) => {
    // A locked surface has nothing real to ask AI about yet, on top of the
    // brief's own `isAssessmentLive` suppression.
    const showAiTriggers = !isEnrollGated && !isAssessmentLive

    const railAndContent = [
        ...(RAIL_SURFACES.has(activeSurface) ? [() => (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={RAIL_ARIA_LABEL}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <StackV
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."

                    items={[() => <Spinner label={RAIL_LOADING_LABEL} />]}
                />
            </ResizableRail>
        )] : []),
        () => (
            <FillAvailable
                at="base"
                explain="Learn content column takes remaining width beside the optional rail so lesson chrome can shrink without overflowing the shell."
                body={() => <>{children}</>}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "layout", component: "LearnShell" }}
            principle="group-boundary"
            explain="Separates the learn surface from floating AI triggers so each region keeps its own seam owner ΓÇö not sibling-stack, because these are distinct section roles rather than repeating peers."
            items={[
                () => (isEnrollGated && enrollGateProps != null ? (
                    <EnrollGate
                        title={enrollGateProps.title}
                        description={enrollGateProps.description}
                        preview={enrollGateProps.preview}
                        price={enrollGateProps.price}
                        onEnroll={enrollGateProps.onEnroll}
                    />
                ) : (
                    <Stage
                        fill="viewport"
                        canvas={() => (
                            <StackH
                                principle="layout-split"
                                explain="Major layout split ΓÇö not block-boundary, because this separates the optional rail from the lesson body rather than adjacent blocks."
                                items={railAndContent}
                            />
                        )}
                    />
                )),
                () => (showAiTriggers ? (
                    <StackV
                        principle="sibling-stack"
                        explain="Same-kind peer stack of AI trigger chrome ΓÇö not group-boundary, because FAB and selection-ask are alternate trigger peers rather than section groups."
                        items={[
                            () => (
                                <ContentAiFab
                                    onOpen={onOpenAiChat}
                                    isOpen={isAiChatOpen}
                                />
                            ),
                            ...(selectionAsk != null
                                ? [
                                    () => (
                                        <ContentAiSelectionAsk
                                            onOpen={onOpenSelectionAsk}
                                            anchor={selectionAsk.anchor}
                                            isNew={selectionAsk.isNew}
                                        />
                                    ),
                                ]
                                : []),
                        ]}
                    />
                ) : null),
            ]}
        />
    )
}

export { LearnShell }

import React, { useEffect, useMemo, useState } from "react"
import { CheckCircleIcon, SparkleIcon, XCircleIcon } from "@phosphor-icons/react"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnumChip } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { InlineIconLabel } from "@sb-components/composites/text/InlineIconLabel/InlineIconLabel"
import { MODEL_CATEGORY_MAP, type AiModelCategory } from "@sb-components/starci/blocks/learn/SubmissionScoreCard/SubmissionScoreCard"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"

/**
 * `SubmissionAttemptsDrawer` ΓÇö a presentational overlay drawer listing every
 * past graded attempt at one challenge requirement, client-paginated. A row is
 * the select action: tapping it both picks that attempt and closes the drawer.
 * Pagination is owned inside this block (the full attempt list in, sliced
 * 6-at-a-time), not a caller-controlled `currentPage`/`totalPages` pair.
 */

/** One past graded attempt at this challenge requirement. */
export interface SubmissionAttemptRecord {
    /** Stable id ΓÇö the value reported to {@link SubmissionAttemptsDrawerProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in ΓÇö the row turns this into "Attempt N". */
    attemptNumber: number
    /** `null` ΓåÆ not graded yet; the row shows an "ungraded" chip instead of a number. */
    score: number | null
    /** Denominator for `score`. `null` ΓåÆ the score renders bare (no "/max"). */
    maxScore: number | null
    /** Drives the verdict icon + `Chip` tone once `score` is set ΓÇö pass (`success`) or fail (`danger`). */
    isPassing: boolean
    /** Already-humanized relative time (e.g. "2 hours ago"). Absent ΓåÆ the byline row drops the time. */
    processedTimeAgo?: string
    /** The model that graded this attempt. Absent ΓåÆ the byline row does not draw at all (same rule `SubmissionScoreCard` uses). */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
}

/** Props for {@link SubmissionAttemptsDrawer}. */
export interface SubmissionAttemptsDrawerProps {
    /** Whether the drawer is currently open. Forwarded to `DrawerShell`. */
    isOpen: boolean
    /** Open-state change handler (backdrop click, Escape, close button, or a row selection). Forwarded to `DrawerShell`. */
    onOpenChange: (open: boolean) => void
    /** The FULL attempt history (newest first) ΓÇö this block paginates it client-side, same as real `src`. */
    attempts: Array<SubmissionAttemptRecord>
    /** The attempt currently being viewed ΓÇö highlighted with a trailing check. */
    selectedAttemptId?: string
    /** Fired with an attempt id when the reader taps its row. The drawer closes itself right after (same gesture as real `src`). */
    onSelect: (attemptId: string) => void
    /** `true` ΓåÆ this list's own fetch is in flight; the drawer shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) ΓåÆ the drawer falls to its empty message. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the drawer falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler ΓÇö paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button ΓÇö required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** Which edge the panel slides in from. Real `src` picks bottom-on-mobile itself; this port leaves that call to the caller. @default "right" */
    placement?: "top" | "bottom" | "left" | "right"
}

/** Fixed, block-owned title (┬º14d.1) ΓÇö real `src` appends the live count, so this does too. */
const DRAWER_TITLE = "Submission history"
const EMPTY_TITLE = "No submissions yet"
const ERROR_TITLE = "Couldn't load the submission history"
const PAGER_ARIA_LABEL = "Submission history pagination"
const UNGRADED_LABEL = "Ungraded"

/** Attempts per page ΓÇö same constant real `src` uses. */
const HISTORY_PAGE_SIZE = 6
/** How many skeleton rows mirror the list while `attempts` hasn't landed yet. */
const SKELETON_ATTEMPT_COUNT = 3

/** One attempt's verdict `Chip` shape ΓÇö tone/icon/text, all derived from data. */
const scoreChipFor = (attempt: SubmissionAttemptRecord): { tone: "success" | "danger" | "default"; icon?: typeof CheckCircleIcon; text: string } => {
    if (attempt.score == null) {
        return { tone: "default", text: UNGRADED_LABEL }
    }
    return {
        tone: attempt.isPassing ? "success" : "danger",
        icon: attempt.isPassing ? CheckCircleIcon : XCircleIcon,
        text: attempt.maxScore != null ? `${attempt.score}/${attempt.maxScore}` : `${attempt.score}`,
    }
}

/** Turns one attempt into a {@link SurfaceCardListItem}'s free-form `content` ΓÇö mirrors real `src`'s row exactly: attempt line + verdict chip + time-ago on line 1, model byline on line 2. */
const attemptRowContent = (attempt: SubmissionAttemptRecord, isSelected: boolean) => {
    const chip = scoreChipFor(attempt)

    const attemptLabelAndChip = [
        () => (
            <Typography
                text={`Attempt ${attempt.attemptNumber}`}
                size="sm"
                weight="medium"

            />
        ),
        () => <Chip tone={chip.tone} icon={chip.icon} text={chip.text} />,
    ]

    // justify="between" pushes the timeago to the far edge ΓÇö the PARENT does the
    // pushing, not a child margin; the label+chip stay grouped in their own inner track
    // so `between` only ever splits two things, not three.
    const attemptLineContent = [
        () => <StackH principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            items={attemptLabelAndChip} />,
        ...(attempt.processedTimeAgo != null ? [() => (
            <Typography
                text={attempt.processedTimeAgo}
                size="xs"
                color="muted"

            />
        )] : []),
    ]

    const bylineContent = [
        () => (
            <InlineIconLabel
                icon={SparkleIcon}
                tone="default"
                size="xs"
                label={`Graded by ${attempt.gradedByModel}`}
            />
        ),
        ...(attempt.modelCategory != null ? [() => (
            <EnumChip
                value={attempt.modelCategory ?? ""}
                map={MODEL_CATEGORY_MAP}

            />
        )] : []),
    ]

    const rowContent = [
        () => (
            <StackH
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={attemptLineContent}
            />
        ),
        ...(attempt.gradedByModel != null ? [() => (
            <StackH at="sm" principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={bylineContent}  />
        )] : []),
    ]

    // highlight-exception: the selected row's tint is baked into the row's own
    // content wrapper (a plain, un-tightened `<div>`), since `SurfaceCardListItem`
    // no longer takes a raw `className` ΓÇö same class real `src`'s
    // `SurfaceListCardItem` uses.
    return (
        <div className={isSelected ? "bg-accent-soft hover:bg-accent-soft" : undefined}>
            <StackV gap={2} items={rowContent} />
        </div>
    )
}

/**
 * The attempts-history drawer. See the file header for the real-`src` rebuild
 * and why selecting a row closes the drawer in the same gesture.
 *
 * @param props - {@link SubmissionAttemptsDrawerProps}
 */
const SubmissionAttemptsDrawer = ({
    isOpen,
    onOpenChange,
    attempts,
    selectedAttemptId,
    onSelect,
    isLoading = false,
    isEmpty = false,
    error,
    onRetry,
    retryLabel,
    placement = "right",
}: SubmissionAttemptsDrawerProps) => {
    const [page, setPage] = useState(1)

    // reset to the first page whenever the drawer opens ΓÇö same as real `src`.
    useEffect(() => {
        if (isOpen) {
            setPage(1)
        }
    }, [isOpen])

    const totalPages = Math.max(1, Math.ceil(attempts.length / HISTORY_PAGE_SIZE))
    const pagedAttempts = useMemo(
        () => attempts.slice((page - 1) * HISTORY_PAGE_SIZE, page * HISTORY_PAGE_SIZE),
        [attempts, page],
    )

    const emptyContent: AsyncContentEmptyProps = {
        title: EMPTY_TITLE,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const skeletonRows = Array.from({ length: SKELETON_ATTEMPT_COUNT }, () => () => (
        <div className="h-16 w-full rounded-2xl bg-default/40" />
    ))

    // `selected` (a trailing check) is only wired for the FIXED title/subtitle row
    // shape ΓÇö this row uses free-form `content` instead (2 lines, richer than that
    // shape fits), so the highlight is baked into `attemptRowContent`'s own wrapper
    // div, same class real `src`'s `SurfaceListCardItem` uses.
    const items: Array<SurfaceCardListItem> = pagedAttempts.map((attempt) => ({
        key: attempt.id,
        content: () => attemptRowContent(attempt, attempt.id === selectedAttemptId),
        onPress: () => {
            onSelect(attempt.id)
            onOpenChange(false)
        },
    }))

    const listAndPager = [
        () => (
            <SurfaceCardList
                items={items}


            />
        ),
        ...(totalPages > 1 ? [() => (
            // `Pagination` hard-codes its own internal `aria-label` (┬º4) ΓÇö the
            // wrapping `<nav>` is how this block's own accessible name still
            // gets attached, same convention `CourseQaQuestionList` uses.
            <nav aria-label={PAGER_ARIA_LABEL}>
                <Pagination
                    currentPage={page}
                    totalPages={totalPages}
                    onPageChange={setPage}

                />
            </nav>
        )] : []),
    ]

    return (
        <DrawerShell
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            placement={placement}
            title={`${DRAWER_TITLE} ┬╖ ${attempts.length}`}
            body={() => (
                <AsyncContent
                    isLoading={isLoading}
                    skeleton={() => (
                        <StackV
                            principle="sibling-stack"
                            explain="Skeleton attempt rows ΓÇö not group-boundary, because these are peer loading placeholders."
                            items={skeletonRows}
                        />
                    )}
                    isEmpty={isEmpty}
                    emptyContent={emptyContent}
                    error={error}
                    errorContent={errorContent}
                    content={() => (
                        <StackV
                            principle="content-row"
                            explain="Attempt list over optional pager ΓÇö not sibling-stack, because these are related content regions."
                            items={listAndPager}
                        />
                    )}
                />
            )}
        />
    )
}

export { SubmissionAttemptsDrawer }
